create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.habits (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null check (char_length(name) between 1 and 120), description text, frequency text not null default 'daily' check (frequency in ('daily','weekly','custom')), target_per_week integer check (target_per_week is null or target_per_week between 1 and 7), color text, icon text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (id,user_id));
create table public.habit_logs (id uuid primary key default gen_random_uuid(), habit_id uuid not null, user_id uuid not null references auth.users(id) on delete cascade, completed_on date not null, note text, created_at timestamptz not null default now(), foreign key (habit_id,user_id) references public.habits(id,user_id) on delete cascade, unique (habit_id,completed_on));
create index habits_user_id_idx on public.habits(user_id);
create index habit_logs_habit_id_idx on public.habit_logs(habit_id);
create index habit_logs_user_date_idx on public.habit_logs(user_id,completed_on);
create function public.handle_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at = now(); return new; end; $$;
create trigger on_profiles_updated before update on public.profiles for each row execute function public.handle_updated_at();
create trigger on_habits_updated before update on public.habits for each row execute function public.handle_updated_at();
alter table public.profiles enable row level security;
alter table public.habits enable row level security;
alter table public.habit_logs enable row level security;
create policy profiles_select_own on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy profiles_insert_own on public.profiles for insert to authenticated with check ((select auth.uid()) = id);
create policy profiles_update_own on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
create policy profiles_delete_own on public.profiles for delete to authenticated using ((select auth.uid()) = id);
create policy habits_select_own on public.habits for select to authenticated using ((select auth.uid()) = user_id);
create policy habits_insert_own on public.habits for insert to authenticated with check ((select auth.uid()) = user_id);
create policy habits_update_own on public.habits for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy habits_delete_own on public.habits for delete to authenticated using ((select auth.uid()) = user_id);
create policy habit_logs_select_own on public.habit_logs for select to authenticated using ((select auth.uid()) = user_id);
create policy habit_logs_insert_own on public.habit_logs for insert to authenticated with check ((select auth.uid()) = user_id);
create policy habit_logs_update_own on public.habit_logs for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy habit_logs_delete_own on public.habit_logs for delete to authenticated using ((select auth.uid()) = user_id);
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles(id,display_name) values (new.id, coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email,'@',1))) on conflict (id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
grant usage on schema public to anon, authenticated;
grant select on public.profiles, public.habits, public.habit_logs to anon;
grant select, insert, update, delete on public.profiles, public.habits, public.habit_logs to authenticated;
